mapper.select:
select p.*,c.cur_finish from tb_screen_person p left join tb_screen_sum c on p.id_num=c.id_num

    name like concat('%',#{name},'%')
    and   id_num like concat('%',#{idNum},'%')
    and   screen_id =#{screenId}
    and   p.screen_type =#{screenType}
    and   p.year =#{year}

        and
        (

            first_type IN(

                #{type}

            )

           or
        more_type & #{moreTypeNum}  > 0
           )

    and ( c.last_computed_tomography_time BETWEEN #{startTime}  AND #{endTime})
    and p.deleted=0

   order by id desc
limit #{pageNo},#{pageSize};

select count(DISTINCT p.id) from tb_screen_person p left join tb_screen_sum c on p.id_num=c.id_num

    name like concat('%',#{name},'%')
    and   id_num like concat('%',#{idNum},'%')
    and   screen_id =#{screenId}
    and   p.screen_type =#{screenType}

        and
        (

            first_type IN(

                #{type}
            )

        or
        more_type & #{moreTypeNum}  > 0
        )

    and ( c.last_computed_tomography_time BETWEEN #{startTime}  AND #{endTime})
    and p.deleted=0

select ifnull(max(screen_order),0)
from tb_screen_computed_tomography
where id_num=#{idNum} and screen_type=#{screenType} and `year`=#{year};

select id, screen_id screenId, sync_id syncId, id_num idNum, person_id personId, computed_tomography_code computedTomographyCode, computed_tomography computedTomography, photo_time photoTime, doctor_signature doctorSignature, outcome, screen_order, screen_time screenTime, year, screen_type screenType,remark
from tb_screen_computed_tomography
where id_num=#{idNum}

    and screen_order=#{screenOrder}


    and screen_type=#{screenType}


    and year=#{year}

select count(case when c.outcome=0 then 1 end) normal,count(case when c.outcome=1 then 1 end) suspected
from tb_screen_computed_tomography c  join tb_screen_sum s on s.id_num=c.id_num
where c.screen_type=#{screenType} and c.year=#{year}

SELECT id
FROM tb_screen_computed_tomography
WHERE deleted = 0
  AND person_id = #{personId}
  AND screen_id = #{screenId}
  AND screen_order = #{screenOrder}
  AND screen_type = #{screenType}
  AND year = #{year}

select ifnull(count(*),0)
FROM tb_screen_computed_tomography
WHERE deleted = 0
          AND id_num = #{idNum}
          AND screen_order = #{screenOrder}
          AND screen_type = #{screenType}
          AND year = #{year}

select ifnull(screen_order,0)
from tb_screen_computed_tomography
WHERE deleted = 0
  AND id_num = #{idNum}
  AND screen_type = #{screenType}
  AND year = #{year}
order by screen_order asc
limit 1
